def solve(data):
    import json
    stack=[(json.loads(data),1)]; total=0
    while stack:
        values,depth=stack.pop()
        for value in values:
            if isinstance(value,list):stack.append((value,depth+1))
            else:total+=value*depth
    return str(total)

